$:set -euo pipefail
test -f AGENTS.md
gh auth setup-git
git config user.name 'github-actions[bot]'
git config user.email '41898282+github-actions[bot]@users.noreply.github.com'
node <<'NODE'

const fs=require('fs'),path=require('path'),assert=require('assert');
const completed='Tasks/TasksCompleted', queue='Tasks/User Prompt Task Queue', rejected='Tasks/TasksRejected';
const read=p=>JSON.parse(fs.readFileSync(p,'utf8'));
const write=(p,obj)=>fs.writeFileSync(p,JSON.stringify(obj,null,2)+'\n');
const ids=['1794192853','1794193447']; 
const artifacts={
 '1794192853':['user-prompt-task-1794192853-revision.json'],
 '1794193447':['user-prompt-task-1794193447-wrapper.json','user-prompt-task-1794193447-spec.md']
};
const manifestPath=path.join(completed,'custom-instruction-task-completion.json');
const manifest=read(manifestPath);
assert(manifest.tasks.length===3 && ids.every(id=>manifest.tasks.some(x=>x.id===id&&x.status==='completed')));
const analyticsPath=path.join(completed,'user-prompt-task-1794193968.json');
const analyticsTask=read(analyticsPath);
assert.strictEqual(analyticsTask.status,'completed');
const analyticsArtifact=path.join(completed,'user-prompt-task-1794193968-rule.json');
assert(fs.existsSync(analyticsArtifact));
const templatePath='conversations/conversation-record.template.json';
assert(fs.existsSync(templatePath));
fs.mkdirSync(rejected,{recursive:true});
const now=new Date().toISOString();
for(const id of ids){
 const source=path.join(completed,'user-prompt-task-'+id+'.json');
 const dest=path.join(queue,'user-prompt-task-'+id+'.json');
 assert(fs.existsSync(source)&&!fs.existsSync(dest));
 const task=read(source); assert.strictEqual(task.status,'completed');
 const oldCompletion=task.completion;
 task.status='pending_revision';
 task.rejection={
  acknowledged_at_utc:now,
  reason:'User explicitly rejected the submitted design artifact; no specific replacement criteria supplied.',
  original_completed_artifacts:artifacts[id].map(name=>'Tasks/TasksRejected/'+name),
  prior_completion:oldCompletion,
  accepted:false
 };
 delete task.completed_at_utc;
 delete task.completion;
 write(dest,task);
 fs.unlinkSync(source);
 for(const name of artifacts[id]){
  const oldPath=path.join(completed,name),newPath=path.join(rejected,name);
  assert(fs.existsSync(oldPath)&&!fs.existsSync(newPath));
  fs.renameSync(oldPath,newPath);
 }
}
analyticsTask.completion.files=[analyticsArtifact];
analyticsTask.completion.wrapper_integration='blocked_pending_accepted_wrapper';
analyticsTask.completion.note='Standalone rule specification retained; wrapper compatibility cannot be accepted while the wrapper design is rejected.';
write(analyticsPath,analyticsTask);
manifest.tasks=manifest.tasks.map(item=>ids.includes(item.id)?{
 ...item,task_path:'Tasks/User Prompt Task Queue/user-prompt-task-'+item.id+'.json',
 status:'pending_revision',acceptance:'rejected',
 kind:'rejected_design_draft'
}:item);
manifest.artifacts=manifest.artifacts.map(file=>ids.some(id=>artifacts[id].some(name=>file.endsWith('/'+name)))?file.replace('Tasks/TasksCompleted/','Tasks/TasksRejected/'):file);
manifest.user_rejection={
 recorded_at_utc:now,
 rejected_task_ids:ids,
 rejected_artifacts:ids.flatMap(id=>artifacts[id].map(name=>'Tasks/TasksRejected/'+name)),
 original_scope_instruction:'untouched',
 analytics_template:'untouched',
 analytics_rule:'not_rejected_but_wrapper_integration_blocked',
 next_step:'Redesign requires user criteria; no replacement inferred.'
};
manifest.verification.nested_final_interpretation_present='rejected_design_not_accepted';
manifest.verification.scope_preserved='original_instruction_unchanged; rejected_compaction_not_adopted';
manifest.other_queued_tasks='unchanged';
manifest.current_disposition='one_standalone_rule_design_completed; two_custom_instruction_designs_rejected_and_requeued';
write(manifestPath,manifest);
write(path.join(rejected,'custom-instruction-rejection-record.json'),{
 schema:'terminals.custom-instruction-rejection.v1',
 recorded_at_utc:now,
 user_feedback:'the template is rejected and so is the revision of the user scope revision',
 interpretation:'Custom-instruction wrapper design and condensed scope-instruction revision are rejected.',
 source_commit:'702bc4dbb50d094a834839c97f3bf82b43b4dc22',
 rejected_task_ids:ids,
 pending_revisions:ids.map(id=>'Tasks/User Prompt Task Queue/user-prompt-task-'+id+'.json'),
 rejected_artifacts:manifest.user_rejection.rejected_artifacts,
 unchanged:['Original account scope instruction','conversations/conversation-record.template.json'],
 related:'Task 1794193968 is not rejected; compatibility with a replacement wrapper remains unresolved.'
});
assert(manifest.tasks.filter(x=>x.status==='pending_revision').length===2);
assert(manifest.tasks.filter(x=>x.status==='completed').length===1);
for(const id of ids){
 assert(read(path.join(queue,'user-prompt-task-'+id+'.json')).status==='pending_revision');
 assert(!fs.existsSync(path.join(completed,'user-prompt-task-'+id+'.json')));
 for(const name of artifacts[id])assert(fs.existsSync(path.join(rejected,name)));
}
assert.strictEqual(read(analyticsPath).status,'completed');
console.log('REJECTION_STATUS_VALIDATED');
console.log('REJECTED_AND_REQUEUED='+ids.join(','));
console.log('ANALYTICS_RULE_UNREJECTED_WRAPPER_DEPENDENCY_BLOCKED');

NODE
git add -- Tasks
git diff --cached --check
git commit -m 'Record rejected custom instruction drafts and restore pending revision status'
git push origin HEAD:main
git rev-parse HEAD
